select plan, enterprise_monthly_fee, standard_monthly_fee from (select plan, sum(case when plan = 'enterprise' then monthly_fee else 0 end) enterprise_monthly_fee, sum(case when plan = 'standard' then monthly_fee else 0 end) standard_monthly_fee from subscriptions where customer_id in (18, 31) group by plan) sub where enterprise_monthly_fee >= 43 order by enterprise_monthly_fee desc;
